actions.script:
// each part in its own transaction: one that fails is logged and rolled back, and the others still load
const startUser = ec.user.username || null
for (const name of ['team', 'leadership', 'engineering', 'johnNotes', 'joeNotes']) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('ironstone.commons.KnowledgeDemoServices.load#KnowledgeDemoPart').parameter('part', name).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.error(`Knowledge demo: the part ${name} was not loaded: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
        if (ec.user.username && ec.user.username !== startUser) ec.user.logoutUser()
        ec.user.setEffectiveTime(null)
    }
}

const WIKI = 'org.moqui.resource.WikiServices'
const KNOW = 'ironstone.commons.KnowledgeServices'
const users = {john: 'john.doe', joe: 'joe.developer', bob: 'bob.developer'}
const ids = {john: 'EX_JOHN_DOE', joe: 'ORG_ZIZI_JD', bob: 'ORG_ZIZI_BD'}
const account = (userId) => ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
if (account(ids.john) == null) { ec.logger.warn('The knowledge demo needs the user john.doe (mr-mantle demo data); nothing loaded'); return }
const haveJoe = account(ids.joe) != null
const haveBob = account(ids.bob) != null
const wanted = String(part || '')
const nowMs = Date.now()
const day = 86400000
const call = (name, parameters) => {
    const out = ec.service.sync().name(name).parameters(parameters || {}).call()
    if (ec.message.hasError()) throw new Error(`${name}: ${ec.message.getErrorsString()}`)
    return out || {}
}
// as a demo user at a time before now (days ago, then hours): the versions, history rows and dates are theirs
const as = (who, daysAgo, run) => {
    if ((who === 'joe' && !haveJoe) || (who === 'bob' && !haveBob)) who = 'john'
    ec.user.internalLoginUser(users[who])
    ec.user.setEffectiveTime(nowMs - Math.round(daysAgo * day))
    try { return run() } finally { ec.user.setEffectiveTime(null); ec.user.logoutUser() }
}
const save = (space, path, text, note) => {
    const slash = path.lastIndexOf('/')
    return call(`${WIKI}.update#WikiPage`, {wikiSpaceId: space, parentPath: slash > 0 ? path.substring(0, slash) : null,
        pageName: slash >= 0 ? path.substring(slash + 1) : (path || space), pageText: text, versionNote: note || null})
}
const pageId = (space, path) => ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', space)
        .condition('pagePath', path || null).disableAuthz().one()?.wikiPageId || null
const spaceExists = (space) => ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', space).disableAuthz().one() != null
// the part asked for; an error thrown here is the part's, which the caller logs
const section = (name, run) => { if (name === wanted) run() }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    section('team', () => {
        if (spaceExists('BOSSKB')) return
        as('john', 30, () => {
            call(`${WIKI}.create#WikiSpace`, {wikiSpaceId: 'BOSSKB', description: 'Team handbook', restrictView: 'N', restrictUpdate: 'Y',
                memberList: [{userId: ids.joe, allowView: 'Y', allowUpdate: 'Y'}, {userId: ids.bob, allowView: 'Y', allowUpdate: 'N'}].filter((member) => account(member.userId) != null)})
            save('BOSSKB', '', '# Team handbook\n\nHow we work at Ziziwork Services. Start with [Onboarding](Onboarding), then read the [[Policies]] ' +
                'and the [[Release process|release process]].\n\n- [Office](Office): the building, Wi-Fi and printers\n- [Travel](Policies/Travel): ' +
                'booking and paying for trips\n- [[Policies/Remote work|Remote work]]: still to be written\n', 'The handbook home')
        })
        as('joe', 18, () => save('BOSSKB', 'Onboarding', '# Onboarding\n\nWelcome aboard! Your first week is in [[Onboarding/First week]]. ' +
            'Ask in the team chat whenever something is unclear.\n\n## Accounts\n\n- Mail and calendar: IronStone Comms\n- Files and pages: IronStone Commons\n\n' +
            '## Who to ask\n\n| Topic | Person |\n| --- | --- |\n| The office and Wi-Fi | Bob Developer |\n| Releases | Joe Developer |\n| Everything else | John Doe |\n',
            'First version'))
        as('john', 17, () => save('BOSSKB', 'Onboarding/First week', '# Your first week\n\n1. Set up your mail account in Comms\n' +
            '2. Read the [travel policy](../Policies/Travel)\n3. Meet the team at the weekly sync\n4. Ship something small with the [[Release process]]\n\n' +
            'Back to [Onboarding](../Onboarding).\n', null))
        as('john', 16, () => save('BOSSKB', 'Policies', '# Policies\n\n- [Travel](Policies/Travel)\n- [Expenses](Policies/Expenses)\n' +
            '- [Security](Policies/Security), for the leads\n', null))
        as('john', 15, () => save('BOSSKB', 'Policies/Travel', '# Travel\n\nBook trips through the office. Economy class for flights under six hours.\n\n' +
            'Claim what you paid as in [Expenses](Expenses).\n', 'First version'))
        as('joe', 9, () => save('BOSSKB', 'Policies/Travel', '# Travel\n\nBook trips through the office. Take the train when it is under four hours; ' +
            'economy class for flights under six hours.\n\nClaim what you paid as in [Expenses](Expenses).\n', 'Train first under four hours'))
        as('john', 14, () => save('BOSSKB', 'Policies/Expenses', '# Expenses\n\nSend the receipt within 30 days. Meals on a trip up to 60 a day.\n\n' +
            'See also [[Policies/Travel|Travel]].\n', null))
        as('john', 13, () => {
            save('BOSSKB', 'Policies/Security', '# Security\n\nFor the leads: the door codes change on the first of the month. ' +
                'Ask Bob for the new ones.\n', 'Restricted to the leads')
            const id = pageId('BOSSKB', 'Policies/Security')
            call('update#moqui.resource.wiki.WikiPage', {wikiPageId: id, restrictView: 'Y'})
            call('create#moqui.resource.wiki.WikiPageUser', {wikiPageId: id, userId: ids.john, allowView: 'Y', allowUpdate: 'Y', receiveNotifications: 'N'})
            if (haveBob) call('create#moqui.resource.wiki.WikiPageUser', {wikiPageId: id, userId: ids.bob, allowView: 'Y', allowUpdate: 'N', receiveNotifications: 'N'})
        })
        as('john', 12, () => {
            save('BOSSKB', 'Office', '# Office\n\nThe office is open 8 to 6 on weekdays. Printers and Wi-Fi: [[Office/Wi-Fi and printers]].\n\n' +
                'The floor plan is in the files of this page.\n', null)
            save('BOSSKB', 'Office/Wi-Fi and printers', '# Wi-Fi and printers\n\nNetwork: ziziwork-staff. The guest network is ziziwork-guest.\n\n' +
                'The printer by the kitchen prints on both sides by default.\n', null)
        })
        as('joe', 12, () => save('BOSSKB', 'Release process', '# Release process\n\n1. Merge to main\n2. Tag the release\n3. Deploy\n', 'First draft'))
        as('john', 6, () => {
            save('BOSSKB', 'Release process', '# Release process\n\n1. Merge to main\n2. Tag the release\n3. Deploy\n\n## Rollback\n\n' +
                'Deploy the previous tag again, then say so in the team chat.\n', 'Added the rollback steps')
            call(`${WIKI}.set#PublishedVersion`, {wikiPageId: pageId('BOSSKB', 'Release process'), publishedVersionName: '02'})
        })
        as('joe', 1, () => {
            save('BOSSKB', 'Release process', '# Release process\n\n1. Merge to main once the checks pass\n2. Tag the release\n3. Deploy\n' +
                '4. Watch the error log for an hour\n\n## Rollback\n\nDeploy the previous tag again, then say so in the team chat. ' +
                'Write what happened in [Onboarding](Onboarding) if a new person should know.\n', 'Release checklist from the team review')
            const id = pageId('BOSSKB', 'Release process')
            // the review waiting on john.doe, as request#WikiPageReview makes it, without its tray notification
            const review = ec.entity.makeValue('moqui.resource.wiki.WikiPageReview')
            review.setFields({wikiPageReviewId: 'BOSS_DEMO_WPR_RELEASE', wikiPageId: id, versionName: '03', baseVersionName: '02',
                statusId: 'WprRequested', requestedByUserId: haveJoe ? ids.joe : ids.john, reviewerUserId: ids.john,
                requestedDate: ec.user.nowTimestamp, dueDate: new Date(nowMs + 2 * day), note: 'Please check the new rollback steps before Friday'}, true, null, null)
            review.createOrUpdate()
            call('mantle.party.CommunicationServices.add#WikiPageComment', {wikiPageId: id, subject: 'Release process',
                body: 'I moved the checks before the merge. Watching the error log came from the last incident.'})
        })
        as('john', 11, () => {
            const id = pageId('BOSSKB', 'Office')
            const out = call(`${WIKI}.get#WikiPageAttachment`, {wikiSpaceId: 'BOSSKB', pagePath: id, filename: 'floor-plan.txt'})
            out.attachmentReference.putText('Floor plan of the office\n\nKitchen, Maple room, Board room, desks 1 to 24.\n')
        })
    })
    section('leadership', () => {
        if (spaceExists('BOSSLEAD')) return
        as('john', 20, () => {
            call(`${WIKI}.create#WikiSpace`, {wikiSpaceId: 'BOSSLEAD', description: 'Leadership', restrictView: 'Y', restrictUpdate: 'Y',
                memberList: haveBob ? [{userId: ids.bob, allowView: 'Y', allowUpdate: 'N'}] : []})
            save('BOSSLEAD', '', '# Leadership\n\nFor the leads only. See the [[Hiring plan]].\n', null)
            save('BOSSLEAD', 'Hiring plan', '# Hiring plan\n\nTwo developers in the first quarter, a designer in the second.\n', 'First plan')
        })
    })
    section('engineering', () => {
        if (spaceExists('BOSSENG')) return
        as('john', 10, () => {
            call(`${WIKI}.create#WikiSpace`, {wikiSpaceId: 'BOSSENG', description: 'Engineering notes', repositoryKind: 'db',
                memberList: haveJoe ? [{userId: ids.joe, allowView: 'Y', allowUpdate: 'Y'}] : []})
            save('BOSSENG', '', '# Engineering notes\n\nKept in a git repository: each save is a commit. See [[Build setup]] and the ' +
                '[team handbook](wiki:BOSSKB/Release%20process).\n', 'Engineering notes home')
        })
        as('joe', 8, () => save('BOSSENG', 'Build setup', '# Build setup\n\nUse one toolchain and incremental debug builds.\n', 'How we build'))
        as('joe', 3, () => save('BOSSENG', 'Build setup', '# Build setup\n\nUse one toolchain and incremental debug builds. ' +
            'Keep a separate build cache per worktree.\n', 'Worktree caches'))
    })
    section('johnNotes', () => {
        const notes = as('john', 25, () => call(`${WIKI}.ensure#UserNotesSpace`, {}).wikiSpaceId)
        if (pageId(notes, 'Groceries') != null) return
        const note = (daysAgo, name, text, tags, pinned) => as('john', daysAgo, () => {
            const id = save(notes, name, text, null).wikiPageId
            if (tags.length) call(`${KNOW}.set#PageTags`, {wikiPageId: id, tags: tags})
            if (pinned) call(`${KNOW}.set#PagePinned`, {wikiPageId: id, pinned: true})
        })
        note(24, 'Cabin Wi-Fi', '# Cabin Wi-Fi\n\nNetwork: lakeside-guest. The router is behind the bookshelf.\n', ['Home'], true)
        note(9, 'Ideas for the newsletter', '# Ideas for the newsletter\n\n- A customer story: the Acme rollout\n- Tips: keyboard shortcuts in IronStone\n' +
            '- Who is new on the team\n', ['Work'], false)
        note(4, 'Call with Acme', '# Call with Acme\n\nBob Acme wants the calendar sharing before the end of the month. ' +
            'Send him the [travel policy](wiki:BOSSKB/Policies/Travel) for the visit.\n\n- [ ] Send the quote\n- [ ] Book the Maple room\n', ['Work'], false)
        note(0.2, 'Groceries', '# Groceries\n\n- milk\n- bread\n- coffee beans\n- apples\n', ['Home'], true)
    })
    section('joeNotes', () => {
        if (!haveJoe) return
        as('joe', 5, () => {
            const notes = call(`${WIKI}.ensure#UserNotesSpace`, {}).wikiSpaceId
            if (pageId(notes, 'Conference talk draft') == null) save(notes, 'Conference talk draft', '# Conference talk draft\n\nOpening: why we moved to IronStone.\n', null)
        })
    })
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}
